const issue = $('Get Building Issues').first().json;
const articles = $input.all().map(i => i.json);

// Build full HTML email
const articleHtml = articles.map(a => {
  const keyPoints = (a.key_points || []).map(p => `<li>${p}</li>`).join('');
  return `
  <div style="margin-bottom:32px;border-bottom:1px solid #e5e7eb;padding-bottom:24px;">
    ${a.image_url ? `<img src="${a.image_url}" alt="" style="width:100%;max-height:200px;object-fit:cover;border-radius:8px;margin-bottom:12px;">` : ''}
    <span style="font-size:12px;color:#6b7280;text-transform:uppercase;">${a.icon || ''} ${a.category || ''}</span>
    <h2 style="margin:8px 0;font-size:20px;"><a href="${a.url}" style="color:#111827;text-decoration:none;">${a.title}</a></h2>
    <p style="color:#374151;line-height:1.6;">${a.blurb || a.summary}</p>
    ${keyPoints ? `<ul style="color:#374151;">${keyPoints}</ul>` : ''}
    <a href="${a.url}" style="display:inline-block;margin-top:8px;color:#7c3aed;font-weight:600;">Read → ${a.author ? `<span style="color:#9ca3af;font-weight:400;">via ${a.author}</span>` : ''}</a>
  </div>`;
}).join('');

const fullHtml = `<!DOCTYPE html>
<html>
<head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Flora News #${issue.issue_number}</title></head>
<body style="font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;max-width:600px;margin:0 auto;padding:20px;background:#fff;">
  <div style="text-align:center;padding:20px 0;border-bottom:2px solid #7c3aed;margin-bottom:32px;">
    <h1 style="color:#7c3aed;margin:0;font-size:28px;">🌿 Flora News</h1>
    <p style="color:#6b7280;margin:4px 0;">Issue #${issue.issue_number}</p>
  </div>
  ${issue.intro_html || ''}
  ${issue.sponsor_html ? `<div style="background:#faf5ff;border:1px solid #e9d5ff;border-radius:8px;padding:16px;margin:24px 0;"><p style="margin:0;font-size:12px;color:#6b7280;">SPONSOR</p>${issue.sponsor_html}</div>` : ''}
  ${articleHtml}
  ${issue.outro_html || ''}
  <div style="text-align:center;padding:20px;border-top:1px solid #e5e7eb;margin-top:32px;">
    <p style="color:#9ca3af;font-size:12px;">Flora News • <a href="{{unsubscribe}}" style="color:#9ca3af;">Unsubscribe</a></p>
  </div>
</body></html>`;

return [{ json: { issue_id: issue.id, full_html: fullHtml, article_count: articles.length } }];
